import data from "@/content/interns.json";

export type Intern = { name: string; slug: string; photo: string | null };

// Generated by scripts/import-intern-headshots.mjs from the headshot form.
export const interns: Intern[] = data;

// Clear, close portraits that lead the hero mosaic and face walls.
const SPOTLIGHT = [
  "calvin-trammell",
  "bukola-arikawe",
  "quadri-durodola",
  "nathalie-diane-tchoumi-mbiami",
  "salman-khalil-butt",
  "chinonyelum-cynthia-asogwa",
  "utibe-owoabasi-obot",
  "ugboma-chukwunonso-kyrian",
  "ojukwu-immaculeta-chiamaka",
  "kabiru-soliu",
  "mary-ojo",
  "syed-azlan-shah",
  "adaeze-elizabeth-adeteye",
  "folayan-olumide",
  "maryjudith-ogunaka",
  "oluwafisayomi-adekoya",
  "nnanna-adaobi-evelyn",
  "david-taiwo-aanuoluwa",
];
const rank = (i: Intern) => {
  const s = SPOTLIGHT.indexOf(i.slug);
  return s >= 0 ? s : i.photo ? SPOTLIGHT.length : SPOTLIGHT.length + 1;
};

/** Spotlight portraits first, then everyone else with a headshot, so photo walls lead with real faces. */
export const internsPhotoFirst: Intern[] = [...interns].sort((a, b) => rank(a) - rank(b));

export function initials(name: string): string {
  const parts = name.split(/\s+/);
  return (parts[0][0] + (parts.length > 1 ? parts[parts.length - 1][0] : "")).toUpperCase();
}
